//! Complete native schema -> tokens -> targets -> staged VJP -> AdamW proof.
//! The checked-in synthetic oracle is generated by the pinned upstream model,
//! processor, losses, trainer, and PEFT. No Python or model download is needed.
const std = @import("std");
const ml = @import("ml").graph;
const step = @import("gliner_boundary_train_step.zig");
const objective = @import("gliner_boundary_train_objectives.zig");
const controller = @import("seeded_gradient_trainer.zig");
const schema_mod = @import("../pipelines/extraction_schema.zig");
const processor = @import("../pipelines/gliner_boundary_processor.zig");
const target = @import("gliner_boundary_targets.zig");
const model = @import("../models/gliner_boundary.zig");
const native = @import("../ops/native_compute.zig");
const ops = @import("../ops/ops.zig");
const interpreter = @import("../graph/interpreter.zig");
const fixture = @import("../architectures/gliner_boundary_parity_test.zig");
const Budget = @import("../runtime/bounded_allocator.zig").BoundedAllocator;
const decision_events = @import("gliner_boundary_training_decisions.zig");
const Allocator = std.mem.Allocator;
pub const Mode = enum { full, heads, lora, dora };
const Profiles = struct {
    attention: step.AttentionProfile = .materialized_v1,
    activation: step.ActivationProfile = .retained_v1,
};

/// The regional variants track the actual fixture, compiled-plan, optimizer,
/// and backend owners separately. Existing retained tests keep their allocator.
const RegionalOwners = struct {
    host: Budget,
    backend: Budget,

    fn seal(self: *RegionalOwners, plan: *step.Plan, trainer: *const controller.Trainer) !void {
        const regional = &plan.recomputation.?.graph.regional;
        if (regional.admission != null) return;
        // Finish head compilation before taking the host census. runBound has
        // already supplied every mutable and frozen named parameter as a CT.
        _ = try plan.recomputedHeadAdmission();
        const update = try trainer.nativeUpdateAdmission();
        try std.testing.expect(trainer.active_binding);
        try std.testing.expect(regional.budget.live <= self.host.live);
        try std.testing.expect(regional.regional_admission.managed_parameter_bytes <= self.backend.live);
        const admitted = try plan.sealRecomputedAdmission(.{
            // Includes both fixture files, parsed source metadata, both cached
            // plans and the optimizer's original weights/m/v/accumulation.
            // Replace this region's live compiler owner with its full cap.
            .fixed_host_bytes = self.host.live - regional.budget.live,
            .fixed_backend_bytes = self.backend.live,
            .head_host_metadata_bytes = try std.math.add(usize, plan.limits.max_step_host_bytes, try std.math.mul(usize, update.elements, @sizeOf(f32))),
            .head_work = plan.limits.max_step_work,
            .optimizer_transaction_host_bytes = update.host_upper_bound_bytes,
            .optimizer_transaction_work = update.total_work,
        });
        try std.testing.expect(admitted.host_upper_bound_bytes <= self.host.limit);
        try std.testing.expect(admitted.backend_upper_bound_bytes <= self.backend.limit);
    }
};

const DecisionCalls = struct {
    pool: usize = 0,
    relations: usize = 0,
    boundary_loss: usize = 0,
    record: usize = 0,

    fn observe(raw: *anyopaque, event: decision_events.Event) !void {
        const self: *DecisionCalls = @ptrCast(@alignCast(raw));
        switch (event) {
            .pool => self.pool += 1,
            .relations => self.relations += 1,
            .boundary_loss => self.boundary_loss += 1,
            .record => self.record += 1,
        }
    }

    fn check(self: DecisionCalls, plan: *const step.Plan) !void {
        // Recomputing encoder regions must never rerun the detached head
        // decisions, matching, or externally evaluated training objectives.
        try std.testing.expectEqual(@as(usize, @intFromBool(plan.pool_input != null)), self.pool);
        try std.testing.expectEqual(@as(usize, @intFromBool(plan.relation_input != null)), self.relations);
        try std.testing.expectEqual(@as(usize, @intFromBool(plan.pool_input != null)), self.boundary_loss);
        try std.testing.expectEqual(plan.records.len, self.record);
    }
};
const Strings = std.json.ArrayHashMap([]const u8);
const metadata = @import("gliner_boundary_fixture_metadata.zig");
const Sample = struct { text: []const u8, schema_version: u32, schema_json: []const u8, annotations: target.Annotations };
const Batch = struct { id: []const u8, samples: []Sample, expected_record_count: usize, expected_relation_count: usize };
const Parameter = struct { name: []const u8, shape: []const i32, trainable: bool };
const Group = struct { parameters: []const []const u8, lr: f32, weight_decay: f32, betas: [2]f32, eps: f32 };
const ExplicitMask = struct { name: []const u8, shape: []const i64, probability: f32, tensor: []const u8 };
const ExplicitDropout = struct { masks: []const ExplicitMask };
const SharedMetadata = struct {
    version: u32 = 1,
    bindings: []const Strings = &.{},
    encoder_configs: []const model.EncoderConfig = &.{},
    dropout: []const ExplicitDropout = &.{},
};
pub const Microbatch = struct {
    id: []const u8,
    microbatch: u64,
    optimizer_step_before: u64,
    inputs: ?Strings = null,
    inputs_ref: ?usize = null,
    outputs: Strings,
    losses: std.json.ArrayHashMap(f32),
    gradients: std.json.ArrayHashMap(?[]const u8),
    total_loss: f32,
    record_match_count: usize,
    relation_positive_count: usize,
    classification_label_count: usize,
    encoder_forward_calls: usize,
    explicit_dropout: ?ExplicitDropout = null,
    explicit_dropout_ref: ?usize = null,
};
const FlushParameter = struct { weight: []const u8, exp_avg: ?[]const u8, exp_avg_sq: ?[]const u8, state_present: bool, step: u32 };
const Flush = struct { after_microbatch: u64, optimizer_step: u64, microbatches: u32, grad_norm: f64, parameters: std.json.ArrayHashMap(FlushParameter) };
pub const Profile = struct {
    mode: Mode,
    encoder_config: ?model.EncoderConfig = null,
    encoder_config_ref: ?usize = null,
    parameters: []Parameter,
    optimizer_groups: []Group,
    initial: ?Strings = null,
    initial_ref: ?usize = null,
    microbatches: []Microbatch,
    flushes: []Flush,
    mid_window_resume_exact: bool,
    frozen_and_unused_unchanged: bool,
};
pub const Oracle = struct {
    format_version: u32,
    source_commit: []const u8,
    qualification: bool,
    settings: model.HeadConfig,
    dropout: ?struct { probability: f32, peft_probability: f32 } = null,
    tokenizer_fragments: std.json.ArrayHashMap([]const i32),
    tensors: struct { sha256: []const u8, size_bytes: usize },
    optimizer: struct { accumulation_steps: u32, max_grad_norm: f32, consistency_scale: f32, soft_iou_scale: f32, gold_injection_probability: f32 },
    batches: []Batch,
    profiles: []Profile,
    sequence: []const usize,
    shared_metadata: SharedMetadata = .{},

    pub fn resolveMetadata(self: *Oracle) !void {
        const shared = self.shared_metadata;
        try metadata.validate(shared.version, &.{ shared.bindings.len, shared.encoder_configs.len, shared.dropout.len });
        for (self.profiles) |*profile| {
            profile.encoder_config = try metadata.resolve(model.EncoderConfig, profile.encoder_config, profile.encoder_config_ref, shared.encoder_configs);
            profile.initial = try metadata.resolve(Strings, profile.initial, profile.initial_ref, shared.bindings);
            for (profile.microbatches) |*micro| {
                micro.inputs = try metadata.resolve(Strings, micro.inputs, micro.inputs_ref, shared.bindings);
                if (micro.explicit_dropout != null or micro.explicit_dropout_ref != null)
                    micro.explicit_dropout = try metadata.resolve(ExplicitDropout, micro.explicit_dropout, micro.explicit_dropout_ref, shared.dropout);
            }
        }
    }
};

/// Exact captured fragment lookup. Unknown fragments fail instead of using
/// the production tokenizer's deliberately unsupported test-only WordLevel.
pub const FragmentTokenizer = struct {
    fragments: *const std.json.ArrayHashMap([]const i32),
    fn tokenizer(self: *FragmentTokenizer) @import("inference_tokenizer").Tokenizer {
        return .{ .ptr = self, .vtable = &.{ .encode = encode, .encodeInto = encodeInto, .encodeForModel = undefined, .encodeGeneration = undefined, .decode = undefined, .specialTokens = specialTokens, .allSpecialTokenIds = specialIds, .vocabSize = vocabSize, .deinit = undefined } };
    }
    fn encode(raw: *anyopaque, a: Allocator, text: []const u8) ![]i32 {
        const self: *FragmentTokenizer = @ptrCast(@alignCast(raw));
        const ids = self.fragments.map.get(text) orelse {
            std.debug.print("uncaptured training tokenizer fragment: {s}\n", .{text});
            return error.UncapturedTrainingTokenization;
        };
        return a.dupe(i32, ids);
    }
    fn encodeInto(raw: *anyopaque, a: Allocator, text: []const u8, output: *std.ArrayListUnmanaged(i32)) !void {
        const ids = try encode(raw, a, text);
        defer a.free(ids);
        try output.appendSlice(a, ids);
    }
    fn specialTokens(_: *anyopaque) @import("inference_tokenizer").SpecialTokens {
        return .{ .unk_id = 0 };
    }
    fn specialIds(raw: *anyopaque, a: Allocator) ![]u32 {
        const self: *FragmentTokenizer = @ptrCast(@alignCast(raw));
        var out = std.ArrayListUnmanaged(u32).empty;
        errdefer out.deinit(a);
        for (self.fragments.map.keys(), self.fragments.map.values()) |name, ids| {
            if (!std.mem.startsWith(u8, name, "[")) continue;
            if (ids.len != 1 or ids[0] < 0) return error.InvalidFixtureTensor;
            try out.append(a, @intCast(ids[0]));
        }
        return out.toOwnedSlice(a);
    }
    fn vocabSize(_: *anyopaque) usize {
        return 192;
    }
};

pub const Prepared = struct {
    allocator: Allocator,
    schemas: []schema_mod.CompiledSchema,
    pointers: []*const schema_mod.CompiledSchema,
    annotations: []target.Annotations,
    batch: processor.PreparedBatch,
    pub fn init(a: Allocator, source: Batch, tokenizer: *FragmentTokenizer) !Prepared {
        const schemas = try a.alloc(schema_mod.CompiledSchema, source.samples.len);
        errdefer a.free(schemas);
        var initialized: usize = 0;
        errdefer for (schemas[0..initialized]) |*schema| schema.deinit();
        const pointers = try a.alloc(*const schema_mod.CompiledSchema, schemas.len);
        errdefer a.free(pointers);
        const annotations = try a.alloc(target.Annotations, schemas.len);
        errdefer a.free(annotations);
        const items = try a.alloc(processor.Item, schemas.len);
        defer a.free(items);
        for (source.samples, schemas, pointers, annotations, items) |sample, *schema, *pointer, *annotation, *item| {
            try std.testing.expectEqual(@as(u32, 2), sample.schema_version);
            schema.* = try schema_mod.compile(a, sample.schema_json, .{});
            initialized += 1;
            pointer.* = schema;
            annotation.* = sample.annotations;
            annotation.schema_fingerprint = schema.fingerprint;
            item.* = .{ .text = sample.text, .schema = schema };
        }
        return .{ .allocator = a, .schemas = schemas, .pointers = pointers, .annotations = annotations, .batch = try processor.prepare(a, tokenizer.tokenizer(), items, .{ .max_sequence_tokens = 128, .max_total_words = 32 }) };
    }
    pub fn deinit(self: *Prepared) void {
        self.batch.deinit();
        for (self.schemas) |*schema| schema.deinit();
        self.allocator.free(self.schemas);
        self.allocator.free(self.pointers);
        self.allocator.free(self.annotations);
    }
};

fn expectIntegers(reference: *const fixture.TensorFixture, key: []const u8, actual: []const i64) !void {
    const value = try reference.tensor(key);
    try std.testing.expectEqual(@import("../backends/tensor.zig").DType.i64, value.dtype);
    try std.testing.expectEqual(actual.len * 8, value.data.len);
    for (actual, 0..) |number, i| try std.testing.expectEqual(std.mem.readInt(i64, value.data[i * 8 ..][0..8], .little), number);
}
fn expectBooleans(a: Allocator, reference: *const fixture.TensorFixture, key: []const u8, actual: []const bool) !void {
    const values = try reference.booleans(a, key);
    defer a.free(values);
    try std.testing.expectEqualSlices(bool, values, actual);
}
pub fn checkPrepared(a: Allocator, reference: *const fixture.TensorFixture, prepared: *const Prepared, micro: Microbatch) !void {
    inline for (.{ "input_ids", "attention_mask", "text_word_indices", "query_marker_indices", "cls_marker_indices" }) |field| {
        errdefer std.debug.print("training preprocessing field {s}\n", .{field});
        try expectIntegers(reference, micro.inputs.?.map.get(field) orelse return error.MissingFixtureTensor, @field(prepared.batch, field));
    }
    inline for (.{ "text_word_mask", "query_marker_mask", "cls_marker_mask" }) |field| try expectBooleans(a, reference, micro.inputs.?.map.get(field) orelse return error.MissingFixtureTensor, @field(prepared.batch, field));
    var targets = try target.compileBatch(a, prepared.batch.samples, prepared.pointers, prepared.annotations, .{ .gold_capacity = 8 });
    defer targets.deinit();
    try expectBooleans(a, reference, micro.outputs.map.get("mention_mask").?, targets.mention_mask);
    const pairs = try a.alloc(i64, targets.mention_pairs.len * 2);
    defer a.free(pairs);
    for (targets.mention_pairs, 0..) |span, i| {
        pairs[2 * i] = @intCast(span.start);
        pairs[2 * i + 1] = @intCast(span.end);
    }
    try expectIntegers(reference, micro.outputs.map.get("mention_pairs").?, pairs);
    try std.testing.expectEqual(micro.classification_label_count, std.mem.count(bool, targets.classification_mask, &.{true}));
}

pub const MappedParameter = struct { source: Parameter, name: []const u8, initial: []const u8, group: ?usize };
fn nativeName(a: Allocator, source: []const u8) ![]const u8 {
    // PEFT trainable names are already the graph's canonical namespace.
    if (std.mem.indexOf(u8, source, ".lora_") != null) return a.dupe(u8, source);
    var name = source;
    const wrapper = "base_model.model.";
    if (std.mem.startsWith(u8, name, wrapper)) name = name[wrapper.len..];
    const base = ".base_layer.";
    if (std.mem.indexOf(u8, name, base)) |position| name = try std.mem.concat(a, u8, &.{ name[0..position], ".", name[position + base.len ..] });
    if (std.mem.startsWith(u8, name, "encoder.")) name = name["encoder.".len..];
    return a.dupe(u8, name);
}
pub fn mappedParameters(a: Allocator, profile: Profile) ![]MappedParameter {
    const mapped = try a.alloc(MappedParameter, profile.parameters.len);
    for (profile.parameters, mapped) |parameter, *out| {
        var group: ?usize = null;
        for (profile.optimizer_groups, 0..) |candidate, index| for (candidate.parameters) |name| if (std.mem.eql(u8, name, parameter.name)) {
            try std.testing.expect(group == null);
            group = index;
        };
        try std.testing.expectEqual(parameter.trainable, group != null);
        out.* = .{ .source = parameter, .name = try nativeName(a, parameter.name), .initial = profile.initial.?.map.get(parameter.name) orelse return error.MissingFixtureTensor, .group = group };
    }
    for (mapped, 0..) |parameter, i| for (mapped[0..i]) |prior| try std.testing.expect(!std.mem.eql(u8, parameter.name, prior.name));
    return mapped;
}
pub fn findParameter(parameters: []const MappedParameter, name: []const u8) !MappedParameter {
    for (parameters) |parameter| if (std.mem.eql(u8, name, parameter.name)) return parameter;
    std.debug.print("unmapped native training parameter {s}\n", .{name});
    return error.MissingFixtureParameter;
}
pub fn configure(reference: *const fixture.TensorFixture, oracle: Oracle, profile: Profile, mapped: []const MappedParameter) !model.Config {
    var encoder = profile.encoder_config.?;
    const relative = try reference.tensor((try findParameter(mapped, "encoder.rel_embeddings.weight")).initial);
    try std.testing.expectEqual(@as(usize, 2), relative.shape.len);
    try std.testing.expectEqual(@as(i64, @intCast(2 * encoder.position_buckets)), relative.shape[0]);
    // HF's absolute position bound is unused here. Native DeBERTa stores the
    // relative table length and logarithmic bucket limit in this field.
    encoder.max_position_embeddings = @intCast(relative.shape[0]);
    return .{ .version = 3, .architecture_version = 1, .max_len = 4096, .backbone = .small, .head = oracle.settings, .encoder = encoder };
}
fn preparePlan(a: Allocator, config: model.Config, prepared: *const Prepared, mode: Mode, mapped: []const MappedParameter, peft_dropout: f32, profiles: Profiles) !step.Plan {
    var plan = try step.buildWithProfiles(a, config, &prepared.batch, prepared.pointers, .{}, .training, profiles.attention, profiles.activation, .{});
    errdefer plan.deinit();
    if (mode == .lora or mode == .dora) try plan.applyPeft(.{ .kind = if (mode == .dora) .dora else .lora, .rank = 2, .alpha = 3, .dropout = peft_dropout, .targets = &.{"encoder"} }, .{});
    var wrt = std.ArrayListUnmanaged(ml.NodeId).empty;
    defer wrt.deinit(a);
    for (plan.graph.parameters.items) |id| {
        const name = plan.graph.parameterName(plan.graph.node(id));
        if (std.mem.startsWith(u8, name, "__")) continue;
        const parameter = try findParameter(mapped, name);
        const shape = plan.graph.node(id).output_shape;
        try std.testing.expectEqual(parameter.source.shape.len, shape.rank());
        for (parameter.source.shape, shape.dims[0..shape.rank()]) |expected, actual| try std.testing.expectEqual(@as(i64, expected), actual);
        if (parameter.source.trainable) try wrt.append(a, id);
    }
    // The one shared PEFT rewrite above precedes all regional/head cuts.
    try plan.finalizeWithActivationProfile(wrt.items, .{}, profiles.activation);
    try std.testing.expectEqual(profiles.attention, plan.encoder.attention_profile);
    try std.testing.expectEqual(profiles.activation, plan.encoder.activation_profile);
    if (profiles.activation == .layer_recompute_v1) {
        const regional = &plan.recomputation.?.graph.regional;
        try std.testing.expectEqual(@as(usize, config.encoder.num_hidden_layers) + 1, regional.regions.len);
        try std.testing.expectEqual(mode != .heads, regional.needsBackward());
        const replay = try regional.replaySummary();
        try std.testing.expectEqual(mode != .heads, replay.replay_regions != 0);
    } else try std.testing.expect(plan.recomputation == null);
    return plan;
}

fn runBound(a: Allocator, cb: *const ops.ComputeBackend, trainer: *controller.Trainer, plan: *step.Plan, prepared: *const Prepared, parameters: []const MappedParameter, reference: *const fixture.TensorFixture, context: step.StepContext, owners: ?*RegionalOwners) !step.StepResult {
    var leased = try trainer.bind(plan.graph, null);
    defer leased.deinit();
    var frozen = std.ArrayListUnmanaged(interpreter.RuntimeInput).empty;
    defer {
        for (frozen.items) |input| cb.free(input.value);
        frozen.deinit(a);
    }
    for (plan.graph.parameters.items) |id| {
        const name = plan.graph.parameterName(plan.graph.node(id));
        if (std.mem.startsWith(u8, name, "__")) continue;
        const parameter = try findParameter(parameters, name);
        if (parameter.source.trainable) continue;
        const value = try cb.fromFloat32Shape(try reference.floats(parameter.initial), parameter.source.shape);
        frozen.append(a, .{ .node_id = id, .value = value }) catch |err| {
            cb.free(value);
            return err;
        };
    }
    const inputs = try std.mem.concat(a, interpreter.RuntimeInput, &.{ leased.inputs, frozen.items });
    defer a.free(inputs);
    if (owners) |regional| try regional.seal(plan, trainer);
    return plan.run(cb, inputs, &prepared.batch, prepared.pointers, prepared.annotations, context, null);
}

fn expectScalar(label: []const u8, expected: f32, actual: f32, absolute: f32, relative: f32) !void {
    errdefer std.debug.print("training scalar {s}: expected {d}, actual {d}\n", .{ label, expected, actual });
    try fixture.expectFloats(&.{expected}, &.{actual}, absolute, relative);
}
pub fn checkTerms(a: Allocator, terms: objective.Terms, micro: Microbatch) !void {
    inline for (std.meta.fields(objective.Terms)) |field| {
        const key = if (comptime std.mem.eql(u8, field.name, "total")) "total_loss" else try std.fmt.allocPrint(a, "{s}_loss", .{field.name});
        defer if (comptime !std.mem.eql(u8, field.name, "total")) a.free(key);
        const expected = if (comptime std.mem.eql(u8, field.name, "total")) micro.total_loss else micro.losses.map.get(key) orelse 0;
        try expectScalar(key, expected, @field(terms, field.name), 1e-3, 2e-5);
    }
}
fn gradientFor(a: Allocator, cb: *const ops.ComputeBackend, plan: *const step.Plan, result: *const step.StepResult, name: []const u8) !?[]const f32 {
    for (result.presence) |presence| {
        if (!std.mem.eql(u8, name, plan.graph.parameterName(plan.graph.node(presence.parameter)))) continue;
        if (presence.kind == .absent) return null;
        for (result.backward.parameter_ids, result.backward.gradients.outputs) |id, value| if (id == presence.parameter) return try cb.toFloat32(value, a);
        if (presence.kind != .computed_zero) return error.MissingTrainingGradient;
        const zeros = try a.alloc(f32, @intCast(plan.graph.node(presence.parameter).output_shape.numElements().?));
        @memset(zeros, 0);
        return zeros;
    }
    return null;
}
fn checkFlush(reference: *const fixture.TensorFixture, trainer: *const controller.Trainer, mapped: []const MappedParameter, expected: Flush, result: controller.Result) !void {
    try std.testing.expect(result.optimizer_stepped);
    try std.testing.expectEqual(expected.optimizer_step, result.identity.optimizer_step);
    try expectScalar("gradient_norm", @floatCast(expected.grad_norm), @floatCast(result.grad_norm), 2e-3, 5e-4);
    for (trainer.owner.regular_params.items) |slot| {
        const parameter = try findParameter(mapped, slot.name);
        const want = expected.parameters.map.get(parameter.source.name) orelse return error.MissingFixtureParameter;
        errdefer std.debug.print("mixed-step optimizer parameter {s}\n", .{parameter.source.name});
        try std.testing.expectEqual(want.step, slot.adam_step_count);
        const state = trainer.owner.optimizer_state.param_states.get(slot.name) orelse return error.MissingTrainingGradient;
        try std.testing.expectEqual(want.state_present, state.step_count != 0);
        try fixture.expectFloats(try reference.floats(want.weight), slot.weights, 2e-5, 2e-5);
        if (want.exp_avg) |key| try fixture.expectFloats(try reference.floats(key), state.m, 2e-5, 1e-3) else for (state.m) |x| try std.testing.expectEqual(@as(f32, 0), x);
        if (want.exp_avg_sq) |key| try fixture.expectFloats(try reference.floats(key), state.v, 1e-7, 2e-3) else for (state.v) |x| try std.testing.expectEqual(@as(f32, 0), x);
    }
}

fn resumeFresh(a: Allocator, cb: *const ops.ComputeBackend, trainer: *controller.Trainer, parameters: []const controller.Parameter, config: controller.Config, contract: [32]u8) !void {
    try std.testing.expectEqual(@as(u32, 1), trainer.owner.accum_count);
    var temporary = std.testing.tmpDir(.{});
    defer temporary.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/boundary-composed.safetensors", .{temporary.sub_path});
    defer a.free(path);
    try trainer.save(path, contract, null);
    var resumed = try controller.Trainer.init(a, cb, parameters, config);
    var owned = true;
    errdefer if (owned) resumed.deinit();
    var wrong_contract = contract;
    wrong_contract[0] ^= 1;
    try std.testing.expectError(error.TrainingStateFingerprintMismatch, resumed.restore(path, wrong_contract, null));
    try std.testing.expectEqual(@as(u64, 0), resumed.identity().microbatch_step);
    try resumed.restore(path, contract, null);
    try std.testing.expectEqual(trainer.identity(), resumed.identity());
    try std.testing.expectEqual(trainer.owner.accum_count, resumed.owner.accum_count);
    try std.testing.expectEqualSlices(bool, trainer.present, resumed.present);
    for (trainer.owner.regular_params.items, resumed.owner.regular_params.items) |old, fresh| {
        try std.testing.expectEqualStrings(old.name, fresh.name);
        try std.testing.expectEqualSlices(i32, old.dims, fresh.dims);
        try std.testing.expectEqualSlices(f32, old.weights, fresh.weights);
        try std.testing.expectEqualSlices(f32, old.grad_accum, fresh.grad_accum);
        try std.testing.expectEqual(old.adam_step_count, fresh.adam_step_count);
        const old_state = trainer.owner.optimizer_state.param_states.get(old.name).?;
        const fresh_state = resumed.owner.optimizer_state.param_states.get(fresh.name).?;
        try std.testing.expectEqual(old_state.step_count, fresh_state.step_count);
        try std.testing.expectEqualSlices(f32, old_state.m, fresh_state.m);
        try std.testing.expectEqualSlices(f32, old_state.v, fresh_state.v);
    }
    trainer.deinit();
    trainer.* = resumed;
    owned = false;
}

fn runOracle(mode: Mode) !void {
    try runOracleFrom(mode, "training_step");
}

pub fn controlledMasks(a: Allocator, plan: *step.Plan, reference: *const fixture.TensorFixture, micro: Microbatch) !?[]const step.DropoutMask {
    const explicit = micro.explicit_dropout orelse return null;
    const descriptors = try plan.dropoutDescriptors(a);
    defer a.free(descriptors);
    try std.testing.expectEqual(descriptors.len, explicit.masks.len);
    const masks = try a.alloc(step.DropoutMask, explicit.masks.len);
    errdefer a.free(masks);
    for (explicit.masks, masks) |mask, *out| {
        const descriptor = for (descriptors) |value| {
            if (std.mem.eql(u8, value.name, mask.name)) break value;
        } else {
            std.debug.print("unknown controlled source dropout route {s}\n", .{mask.name});
            return error.UnexpectedFixtureDropoutMask;
        };
        try std.testing.expectEqualSlices(i64, descriptor.shape.dims[0..descriptor.shape.rank()], mask.shape);
        try std.testing.expectEqual(descriptor.probability, mask.probability);
        const tensor = try reference.tensor(mask.tensor);
        try std.testing.expectEqualSlices(i64, mask.shape, tensor.shape);
        out.* = .{ .name = mask.name, .values = try reference.floats(mask.tensor) };
    }
    return masks;
}

fn runOracleFrom(mode: Mode, directory: []const u8) !void {
    return runOracleWithProfiles(mode, directory, .{});
}

fn runOracleWithProfiles(mode: Mode, directory: []const u8, profiles: Profiles) !void {
    const limits = step.Limits{};
    var owners = RegionalOwners{
        .host = .{ .backing = std.testing.allocator, .limit = limits.recomputation.max_host_bytes },
        .backend = .{ .backing = std.testing.allocator, .limit = limits.recomputation.max_backend_bytes },
    };
    defer std.debug.assert(owners.host.live == 0 and owners.backend.live == 0);
    const regional = profiles.activation == .layer_recompute_v1;
    const a = if (regional) owners.host.allocator() else std.testing.allocator;
    const backend_allocator = if (regional) owners.backend.allocator() else a;
    const capture_path = try std.fmt.allocPrint(a, "{s}/capture.json", .{directory});
    defer a.free(capture_path);
    const bytes = try fixture.fixtureBytes(a, capture_path);
    defer a.free(bytes);
    var parsed = try std.json.parseFromSlice(Oracle, a, bytes, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();
    try parsed.value.resolveMetadata();
    const oracle = parsed.value;
    try std.testing.expectEqual(@as(u32, 1), oracle.format_version);
    try std.testing.expectEqualStrings("3c913c7369301133d3b7699252074c4303ada50e", oracle.source_commit);
    try std.testing.expect(!oracle.qualification);
    const tensor_path = try std.fmt.allocPrint(a, "{s}/tensors.safetensors", .{directory});
    defer a.free(tensor_path);
    var reference = try fixture.TensorFixture.init(a, tensor_path);
    defer reference.deinit();
    try std.testing.expectEqual(oracle.tensors.size_bytes, reference.reader.file_bytes.len);
    const digest = std.crypto.hash.sha2.Sha256.hash;
    var hash: [32]u8 = undefined;
    digest(reference.reader.file_bytes, &hash, .{});
    try std.testing.expectEqualStrings(oracle.tensors.sha256, &std.fmt.bytesToHex(hash, .lower));
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    const scratch = arena.allocator();
    const profile = blk: {
        for (oracle.profiles) |profile| if (profile.mode == mode) break :blk profile;
        return error.MissingFixtureProfile;
    };
    try std.testing.expect(profile.mid_window_resume_exact and profile.frozen_and_unused_unchanged);
    try std.testing.expectEqualSlices(usize, &.{ 0, 1, 1 }, oracle.sequence);
    try std.testing.expectEqual(@as(usize, 3), profile.microbatches.len);
    const mapped = try mappedParameters(scratch, profile);
    const config = try configure(&reference, oracle, profile, mapped);
    var tokenizer = FragmentTokenizer{ .fragments = &oracle.tokenizer_fragments };
    var prepared: [2]?Prepared = .{ null, null };
    defer for (&prepared) |*item| if (item.*) |*value| value.deinit();
    var plans: [2]?step.Plan = .{ null, null };
    defer for (&plans) |*item| if (item.*) |*value| value.deinit();
    for (oracle.batches, 0..) |batch, i| {
        prepared[i] = try Prepared.init(a, batch, &tokenizer);
        plans[i] = try preparePlan(a, config, &prepared[i].?, mode, mapped, if (oracle.dropout) |dropout| dropout.peft_probability else 0, profiles);
    }
    // Bind the new activation/attention profile into this test's checkpoint
    // contract while preserving the original retained fixture contract.
    var checkpoint_contract = hash;
    if (regional) {
        var contract = std.crypto.hash.sha2.Sha256.init(.{});
        contract.update("antfly.gliner25.regional-oracle.v1\x00");
        contract.update(&hash);
        for (&plans) |*item| {
            _ = try item.*.?.recomputedHeadAdmission();
            contract.update(&item.*.?.fingerprint);
        }
        contract.final(&checkpoint_contract);
    }
    var store = native.WeightStore{ .allocator = backend_allocator, .resident_weights = .empty, .lazy_weights = .empty };
    defer store.deinitOwned();
    var compute = native.NativeCompute.init(backend_allocator, &store, null);
    defer compute.deinit();
    const cb = compute.computeBackend();
    const groups = try scratch.alloc(controller.Group, profile.optimizer_groups.len);
    for (profile.optimizer_groups, groups) |group, *out| out.* = .{ .optimizer = .{ .beta1 = group.betas[0], .beta2 = group.betas[1], .eps = group.eps, .weight_decay = group.weight_decay }, .schedule = .{ .constant = group.lr } };
    var parameters = std.ArrayListUnmanaged(controller.Parameter).empty;
    for (mapped) |parameter| if (parameter.source.trainable) try parameters.append(scratch, .{ .name = parameter.name, .values = try reference.floats(parameter.initial), .dimensions = parameter.source.shape, .group = parameter.group.? });
    try std.testing.expectEqual(@as(usize, switch (mode) {
        .full => 168,
        .heads => 130,
        .lora => 24,
        .dora => 36,
    }), parameters.items.len);
    const optimizer_config = controller.Config{ .groups = groups, .grad_accum_steps = oracle.optimizer.accumulation_steps, .max_grad_norm = oracle.optimizer.max_grad_norm };
    var trainer = try controller.Trainer.init(a, &cb, parameters.items, optimizer_config);
    defer trainer.deinit();
    for (profile.microbatches, oracle.sequence, 0..) |micro, batch_index, index| {
        errdefer std.debug.print("pinned composed training profile {s}/{s}/{s} microbatch {d} ({s})\n", .{ @tagName(mode), @tagName(profiles.attention), @tagName(profiles.activation), index, micro.id });
        const batch = &prepared[batch_index].?;
        const plan = &plans[batch_index].?;
        try checkPrepared(a, &reference, batch, micro);
        try std.testing.expectEqual(micro.microbatch, trainer.identity().microbatch_step);
        try std.testing.expectEqual(micro.optimizer_step_before, trainer.identity().optimizer_step);
        const masks = try controlledMasks(a, plan, &reference, micro);
        defer if (masks) |owned| a.free(owned);
        try std.testing.expectEqual(oracle.dropout != null, masks != null);
        var decisions = DecisionCalls{};
        var result = try runBound(a, &cb, &trainer, plan, batch, mapped, &reference, .{
            .identity = .{ .binding = @splat(0x25), .optimizer_step = micro.optimizer_step_before, .microbatch = micro.microbatch },
            .replay = .{ .seed = 253955, .micro_batch = micro.microbatch },
            .progress = .{ .optimizer_step = micro.optimizer_step_before, .total_optimizer_steps = 2 },
            .scales_override = .{ .gold_injection = oracle.optimizer.gold_injection_probability, .consistency = oracle.optimizer.consistency_scale, .soft_iou = oracle.optimizer.soft_iou_scale },
            .negative_query_draws = try reference.floats(micro.outputs.map.get("negative_uniform").?),
            .require_gold_relation_coverage = true,
            .dropout_masks = masks,
            .decision_observer = if (regional) .{ .context = &decisions, .observe = DecisionCalls.observe } else null,
        }, if (regional) &owners else null);
        defer result.deinit(&cb);
        if (regional) try decisions.check(plan);
        try std.testing.expectEqual(masks != null, result.dropout_fingerprint != null);
        try checkTerms(a, result.terms, micro);
        try std.testing.expectEqual(micro.record_match_count, result.coverage.matched_records);
        try std.testing.expectEqual(micro.relation_positive_count, result.coverage.proposed_gold_relations);
        try std.testing.expectEqual(oracle.batches[batch_index].expected_relation_count, result.coverage.gold_relations);
        var gradient_arena = std.heap.ArenaAllocator.init(a);
        defer gradient_arena.deinit();
        const gradient_allocator = gradient_arena.allocator();
        var gradients = std.ArrayListUnmanaged(controller.Gradient).empty;
        var absent: usize = 0;
        for (mapped) |parameter| {
            if (!parameter.source.trainable) continue;
            errdefer std.debug.print("mixed-step gradient {s}\n", .{parameter.source.name});
            const expected = micro.gradients.map.get(parameter.source.name) orelse return error.MissingFixtureParameter;
            const actual = try gradientFor(gradient_allocator, &cb, plan, &result, parameter.name);
            try std.testing.expectEqual(expected != null, actual != null);
            if (expected) |key| {
                try fixture.expectFloats(try reference.floats(key), actual.?, 5e-4, 8e-4);
                try gradients.append(gradient_allocator, .{ .name = parameter.name, .values = actual.? });
            } else absent += 1;
        }
        try std.testing.expectEqual(micro.gradients.map.count(), parameters.items.len);
        if (index != 0 and (mode == .full or mode == .heads)) try std.testing.expectEqual(@as(usize, 34), absent);
        const update = try trainer.submit(trainer.identity(), result.terms.total, gradients.items, null);
        if (index == 0) {
            try std.testing.expect(!update.optimizer_stepped);
            try resumeFresh(a, &cb, &trainer, parameters.items, optimizer_config, checkpoint_contract);
        }
        if (update.optimizer_stepped) {
            try checkFlush(&reference, &trainer, mapped, profile.flushes[0], update);
            for (&plans) |*item| try item.*.?.advanceParameterEpoch();
        }
    }
    const last = try trainer.flush(trainer.identity(), null);
    try checkFlush(&reference, &trainer, mapped, profile.flushes[1], last);
}

